    18→const soundInstanceAtom = atom(() => createSound());
    19→
    20→const audioPlaybackAtom = atom<AudioPlaybackState>({
    21→  currentTrack: null,
    22→  isPlaying: false,
    23→  currentMs: 0,
    24→});
    25→
    26→const loadTrackAtom = atom(null, (get, set, track: AudioTrack) => {
    27→  const currentState = get(audioPlaybackAtom);
    28→
    29→  // If loading a different track, reset state
    30→  if (currentState.currentTrack?.trackId !== track.trackId) {
    31→    set(audioPlaybackAtom, {
    32→      currentTrack: track,
    33→      isPlaying: false,
    34→      currentMs: 0,
    35→    });
    36→  }
    37→});
    38→
    39→const setIsPlayingAtom = atom(null, (get, set, isPlaying: boolean) => {
    40→  const currentState = get(audioPlaybackAtom);
    41→  set(audioPlaybackAtom, {
    42→    ...currentState,
    43→    isPlaying,
    44→  });
    45→});
    46→
    47→const setCurrentMsAtom = atom(null, (get, set, currentMs: number) => {
    48→  const currentState = get(audioPlaybackAtom);
    49→  set(audioPlaybackAtom, {
    50→    ...currentState,
    51→    currentMs,
    52→  });
    53→});
    54→
    55→const resetPlaybackAtom = atom(null, (get, set) => {
    56→  const currentState = get(audioPlaybackAtom);
